  CONSTRAINT fk_dashboard_widgets_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_dashboard_widgets_creator FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Dashboard widgets arranged by users';

-- >>> import_jobs.sql
-- ====================================
-- import_jobs
-- Bulk import job tracking. Each row represents a single import
-- operation from an external source (GitHub, Jira, Linear, CSV).
-- The worker updates processed_items / failed_items as it progresses.
-- ====================================
CREATE TABLE import_jobs (
  id                   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id            BINARY(16) NOT NULL                     COMMENT 'UUID v7, the only externally visible ID',
  workspace_id         INT UNSIGNED NOT NULL                    COMMENT 'Internal FK to workspaces.id',
  project_id           INT UNSIGNED NULL                        COMMENT 'Internal FK to projects.id (target project)',
  initiated_by_user_id INT UNSIGNED NULL                        COMMENT 'Internal FK to users.id (who started the import)',

  source               ENUM('github','jira','linear','csv') NOT NULL COMMENT 'Import source type',
  status               ENUM('pending','running','completed','failed','cancelled') NOT NULL DEFAULT 'pending' COMMENT 'Lifecycle state',
  total_items          INT UNSIGNED NOT NULL DEFAULT 0          COMMENT 'Total items to import',
  processed_items      INT UNSIGNED NOT NULL DEFAULT 0          COMMENT 'Successfully processed items',
  failed_items         INT UNSIGNED NOT NULL DEFAULT 0          COMMENT 'Items that failed to import',
  config_json          JSON NOT NULL                            COMMENT 'Source-specific import configuration. Plaintext and returned by the read endpoints, so it must never hold a credential: the API rejects credential-shaped key names at every nesting level, and checks a per-source allow-list for sources that have declared their keys (see internal/importer). External-service credentials belong in user_integrations / ai_providers, which are encrypted',
  error_log            TEXT NULL                                COMMENT 'Aggregated error log',
  started_at           DATETIME(3) NULL                         COMMENT 'When the worker began processing',
  completed_at         DATETIME(3) NULL                         COMMENT 'When the import finished (success or failure)',

  sort_weight          INT NOT NULL DEFAULT 0                   COMMENT 'Display order',
  notes                TEXT NULL                                COMMENT 'Admin notes',
  enabled              BOOLEAN NOT NULL DEFAULT TRUE            COMMENT 'Enabled flag',
  updated_at           TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_import_jobs_public_id (public_id),
  UNIQUE KEY uniq_import_jobs_workspace_public_id (workspace_id, public_id),
  KEY idx_import_jobs_workspace_id_status (workspace_id, status),

  CONSTRAINT fk_import_jobs_workspace FOREIGN KEY (workspace_id)         REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_import_jobs_project   FOREIGN KEY (project_id)           REFERENCES projects(id)   ON DELETE SET NULL,
  CONSTRAINT fk_import_jobs_initiator FOREIGN KEY (initiated_by_user_id) REFERENCES users(id)      ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Bulk import job tracking';

-- >>> intake_items.sql
-- ====================================
-- intake_items
-- Intake triage queue. Items arrive from signals or manual entry,
-- scored by AI, and triaged into tasks or discarded.
-- ====================================
CREATE TABLE intake_items (
  id                  INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id           BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id        INT UNSIGNED NOT NULL                   COMMENT 'Internal FK to workspaces.id',
  signal_id           INT UNSIGNED NULL                       COMMENT 'Origin signal (NULL = manual)',
  task_id             INT UNSIGNED NULL                       COMMENT 'Converted task (NULL = not yet converted)',
  triaged_by_user_id  INT UNSIGNED NULL                       COMMENT 'User who triaged this item',

  title               VARCHAR(500) NOT NULL                   COMMENT 'Item title',
  body                MEDIUMTEXT NULL                         COMMENT 'Item body / details',
  triage_status       ENUM('pending','accepted','rejected','snoozed','duplicate') NOT NULL DEFAULT 'pending' COMMENT 'Current triage state',
  snooze_until        DATETIME(3) NULL                        COMMENT 'Snooze expiry (NULL = not snoozed)',
  ai_score            DECIMAL(3,2) NULL                       COMMENT '0.00-1.00',
  ai_reasoning        TEXT NULL                               COMMENT 'AI reasoning for the score',
  scored_at           DATETIME(3) NULL                        COMMENT 'When AI scoring was performed',

  sort_weight         INT NOT NULL DEFAULT 0                  COMMENT 'Display order',
  notes               TEXT NULL                               COMMENT 'Admin notes',
  enabled             BOOLEAN NOT NULL DEFAULT TRUE           COMMENT 'Enabled flag',
  updated_at          TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_intake_items_public_id (public_id),
  UNIQUE KEY uniq_intake_items_workspace_public_id (workspace_id, public_id),
  KEY idx_intake_items_workspace_id_status (workspace_id, triage_status),
  KEY idx_intake_items_workspace_id_snooze (workspace_id, snooze_until),
  KEY idx_intake_items_signal_id (signal_id),

  CONSTRAINT fk_intake_items_workspace  FOREIGN KEY (workspace_id)       REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_intake_items_signal     FOREIGN KEY (signal_id)          REFERENCES signals(id)    ON DELETE SET NULL,
  CONSTRAINT fk_intake_items_task       FOREIGN KEY (task_id)            REFERENCES tasks(id)      ON DELETE SET NULL,
  CONSTRAINT fk_intake_items_triaged_by FOREIGN KEY (triaged_by_user_id) REFERENCES users(id)      ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Intake triage queue';

-- >>> integration_source_mappings.sql
-- ====================================
-- integration_source_mappings
-- Routes an inbound webhook delivery to the workspace that owns the
-- external source it came from. Every /webhooks/* receiver identifies
-- its sender (GitHub repository, Slack team, Google push channel) and
-- looks the sender up here; without a row the delivery has no tenant
-- and is rejected rather than routed to an arbitrary workspace.
--
-- (provider, external_key) is UNIQUE across the whole instance, not per
-- workspace: one external source belongs to exactly one tenant, so the
-- routing decision can never be ambiguous. `enabled = FALSE` pauses
-- routing while keeping the claim; releasing the source for another
-- workspace requires deleting the row.
-- ====================================
CREATE TABLE integration_source_mappings (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id — the tenant inbound deliveries from this source are routed to',

  provider ENUM('github','slack','google') NOT NULL COMMENT 'Which /webhooks/* receiver this mapping routes',
  external_key VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_bin NOT NULL COMMENT 'Provider-side sender identity, matched byte-for-byte against the delivery: github = repository.id as decimal digits, slack = team_id, google = X-Goog-Channel-ID',
  label VARCHAR(255) NOT NULL COMMENT 'Display-only name for the source (e.g. GitHub owner/repo, Slack workspace name, watched Drive folder)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag — FALSE pauses routing without releasing the (provider, external_key) claim',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_integration_source_mappings_public_id (public_id),
  UNIQUE KEY uniq_integration_source_mappings_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_integration_source_mappings_provider_key (provider, external_key),
  KEY idx_integration_source_mappings_workspace_provider (workspace_id, provider, enabled),

  CONSTRAINT fk_integration_source_mappings_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Maps an external webhook sender to the workspace that owns it';

-- >>> labels.sql
-- ====================================
-- labels
-- Hierarchical colored labels. Can be workspace-wide (project_id IS NULL)
-- or project-scoped.
-- ====================================
CREATE TABLE labels (
  id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id       BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id    INT UNSIGNED NOT NULL                   COMMENT 'Internal FK to workspaces.id',
  project_id      INT UNSIGNED NULL                       COMMENT 'NULL = workspace-wide label',
  parent_label_id INT UNSIGNED NULL                       COMMENT 'Self-ref for hierarchy; NULL = root',
  created_by_user_id INT UNSIGNED NULL                    COMMENT 'Creator user.id (audit field; NULL when creator is removed)',

  name            VARCHAR(64) NOT NULL COMMENT 'Display name',
  color           VARCHAR(16) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '#6b7280' COMMENT 'Hex color',
  description     VARCHAR(255) NULL COMMENT 'Optional description',

  sort_weight     INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes           TEXT NULL COMMENT 'Admin notes',
  enabled         BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at      TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_labels_public_id (public_id),
  UNIQUE KEY uniq_labels_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_labels_workspace_id_project_id_name_active (workspace_id, project_id, name, active),
  KEY idx_labels_workspace_id_project_id_enabled (workspace_id, project_id, enabled),
  KEY idx_labels_parent_label_id (parent_label_id),
  KEY idx_labels_created_by_user_id (created_by_user_id),

  CONSTRAINT fk_labels_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_labels_project   FOREIGN KEY (project_id)   REFERENCES projects(id)   ON DELETE CASCADE,
  CONSTRAINT fk_labels_parent    FOREIGN KEY (parent_label_id) REFERENCES labels(id) ON DELETE SET NULL,
  CONSTRAINT fk_labels_creator   FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Hierarchical colored labels';

-- >>> lenses.sql
-- ====================================
-- lenses
-- Saved views (filter + sort + groupBy) for task queries.
-- Can be workspace-wide (project_id IS NULL) or project-scoped.
-- ====================================
CREATE TABLE lenses (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  project_id INT UNSIGNED NULL COMMENT 'Internal FK to projects.id (NULL = workspace-wide)',
  creator_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  name VARCHAR(100) NOT NULL COMMENT 'Display name',
  description VARCHAR(500) NULL COMMENT 'Optional public-facing description shown on the share page',
  lens_json JSON NOT NULL COMMENT 'Serialized Lens object (filter, sort, groupBy)',
  is_default BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Default lens for the scope',
  is_public BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Whether the lens is publicly shared',
  public_token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'SHA-256 hex of the public share URL token; the plaintext is handed to the publisher once and never stored, so a leak of this table does not yield working share URLs. NULL while the lens is not published. Same shape as calendar_public_shares.token_hash — capability tokens are hashed at rest everywhere.',
  shared_at DATETIME(3) NULL COMMENT 'Timestamp when first shared publicly',
  safety_checked_at DATETIME(3) NULL COMMENT 'Timestamp of last AI safety check',
  archived_at DATETIME(3) NULL COMMENT 'Set when lens is archived (distinct from enabled)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_lenses_public_id (public_id),
  UNIQUE KEY uniq_lenses_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_lenses_workspace_id_project_id_name_active (workspace_id, project_id, name, active),
  UNIQUE KEY uniq_lenses_public_token_hash (public_token_hash),
  KEY idx_lenses_workspace_id_archived_at (workspace_id, archived_at),
  KEY idx_lenses_workspace_id_project_id_enabled (workspace_id, project_id, enabled),
  KEY idx_lenses_workspace_id_creator_id (workspace_id, creator_id),

  CONSTRAINT fk_lenses_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_lenses_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_lenses_creator FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Saved task query views';

-- >>> mcp_invocations.sql
-- ====================================
-- mcp_invocations
-- Audit record for every MCP tool invocation. Arguments and results are
-- stored post-redaction (no raw secrets).
-- ====================================
CREATE TABLE mcp_invocations (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id (PAT owner)',
  agent_id INT UNSIGNED NULL COMMENT 'Internal FK to ai_agents.id when the invoking token acts on behalf of an AI agent. Copied from mcp_tokens.agent_id at invocation time so the attribution survives the token being revoked. NULL means a human-owned token, which is what makes the user/agent distinction in v_workspace_activity decidable',
  task_id INT UNSIGNED NULL COMMENT 'Internal FK to tasks.id when applicable',

  tool_name VARCHAR(128) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'MCP tool name (e.g., create_task)',
  arguments_redacted_json JSON NOT NULL COMMENT 'Redacted arguments',
  result_redacted_json JSON NULL COMMENT 'Redacted result payload',
  status ENUM('ok','error','denied') NOT NULL COMMENT 'Outcome',
  error_code VARCHAR(128) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Error code when status != ok',
  duration_ms INT UNSIGNED NULL COMMENT 'Wall-clock duration in milliseconds',
  invoked_at DATETIME(3) NOT NULL COMMENT 'Invocation start time (millisecond precision)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_mcp_invocations_public_id (public_id),
  UNIQUE KEY uniq_mcp_invocations_workspace_public_id (workspace_id, public_id),
  KEY idx_mcp_invocations_workspace_id_invoked_at (workspace_id, invoked_at),
  KEY idx_mcp_invocations_workspace_id_user_id (workspace_id, user_id),
  KEY idx_mcp_invocations_workspace_id_agent_id (workspace_id, agent_id),
  KEY idx_mcp_invocations_created_at (created_at),

  CONSTRAINT fk_mcp_invocations_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_mcp_invocations_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_mcp_invocations_agent FOREIGN KEY (agent_id) REFERENCES ai_agents(id) ON DELETE SET NULL,
  CONSTRAINT fk_mcp_invocations_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='MCP tool invocation audit';

-- >>> mcp_tokens.sql
-- ====================================
-- mcp_tokens
-- Personal access tokens used by MCP clients (Claude Desktop, mcp-cli, ...).
-- Only the SHA-256 hash is stored.
-- ====================================
CREATE TABLE mcp_tokens (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id (token owner)',
  agent_id INT UNSIGNED NULL COMMENT 'Internal FK to ai_agents.id when the token acts on behalf of an AI agent',

  name VARCHAR(255) NOT NULL COMMENT 'Human-readable label',
  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the bearer token',
  token_prefix CHAR(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Leading chars shown as hint',
  scopes_json JSON NOT NULL COMMENT 'Array of granted MCP tool scopes',
  expires_at DATETIME(3) NULL COMMENT 'Expiry time (null = never)',
  last_used_at DATETIME(3) NULL COMMENT 'Last successful use',
  revoked_at DATETIME(3) NULL COMMENT 'Explicit revocation time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_mcp_tokens_public_id (public_id),
  UNIQUE KEY uniq_mcp_tokens_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_mcp_tokens_token_hash (token_hash),
  KEY idx_mcp_tokens_workspace_id_user_id (workspace_id, user_id),

  CONSTRAINT fk_mcp_tokens_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_mcp_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_mcp_tokens_agent FOREIGN KEY (agent_id) REFERENCES ai_agents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='MCP personal access tokens';

-- >>> mentions.sql
-- ====================================
-- mentions
-- @mention cache extracted from markdown in task descriptions
-- and comments. Can be re-extracted; serves as a fast lookup
-- for notification fan-out.
-- ====================================
CREATE TABLE mentions (
  id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id         BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id      INT UNSIGNED NOT NULL,
  mentioned_user_id INT UNSIGNED NOT NULL,
  actor_user_id     INT UNSIGNED NULL,

  task_id           INT UNSIGNED NULL,
  comment_id        INT UNSIGNED NULL,
  source            ENUM('task_description','comment') NOT NULL,

  sort_weight       INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes             TEXT NULL COMMENT 'Admin notes',
  enabled           BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at        TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_mentions_public_id (public_id),
  UNIQUE KEY uniq_mentions_workspace_public_id (workspace_id, public_id),
  KEY idx_mentions_workspace_mentioned_user (workspace_id, mentioned_user_id),
  KEY idx_mentions_task_id (task_id),
  KEY idx_mentions_comment_id (comment_id),

  CONSTRAINT fk_mentions_workspace FOREIGN KEY (workspace_id)      REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_mentions_mentioned FOREIGN KEY (mentioned_user_id) REFERENCES users(id)      ON DELETE CASCADE,
  CONSTRAINT fk_mentions_actor     FOREIGN KEY (actor_user_id)     REFERENCES users(id)      ON DELETE SET NULL,
  CONSTRAINT fk_mentions_task      FOREIGN KEY (task_id)           REFERENCES tasks(id)      ON DELETE CASCADE,
  CONSTRAINT fk_mentions_comment   FOREIGN KEY (comment_id)        REFERENCES comments(id)   ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='@mention cache (re-extractable from markdown)';

-- >>> notification_preferences.sql
-- ====================================
-- notification_preferences
-- Granular per-user notification preferences. Each row controls
-- one (event_category, channel) pair; is_muted suppresses delivery.
-- ====================================
CREATE TABLE notification_preferences (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id      BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id   INT UNSIGNED NOT NULL,
  user_id        INT UNSIGNED NOT NULL,

  event_category VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL
    COMMENT 'task.lifecycle, task.comment, task.mention, relation, timebox, ai, etc.',
  channel        ENUM('in_app','email','push') NOT NULL,
  is_muted       BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'TRUE = suppress this category+channel',

  sort_weight    INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes          TEXT NULL COMMENT 'Admin notes',
  enabled        BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at     TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_notif_prefs_public_id (public_id),
  UNIQUE KEY uniq_notif_prefs_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_notif_prefs_user_ws_cat_chan (user_id, workspace_id, event_category, channel),
  KEY idx_notif_prefs_workspace_user (workspace_id, user_id),

  CONSTRAINT fk_notif_prefs_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_notif_prefs_user      FOREIGN KEY (user_id)      REFERENCES users(id)      ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Granular per-user notification preferences';

-- >>> notifications.sql
-- ====================================
-- notifications
-- Per-user notification entries produced by eventbus fan-out when workspace
-- events occur. Each row represents one notification to one recipient.
-- ====================================
CREATE TABLE notifications (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  recipient_user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id, the user who receives this notification',
  actor_user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id, who triggered the event (null for system)',
  -- BIGINT UNSIGNED to match events.id, which is a BIGINT UNSIGNED exception
  -- (append-only log expected to grow past the 4.29B INT UNSIGNED ceiling).
  source_event_id BIGINT UNSIGNED NULL COMMENT 'Internal FK to events.id (BIGINT UNSIGNED) used for at-least-once dedup; null for non-event-driven paths (scheduler, system)',

  event_type VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Matches eventbus event types (e.g. task.created, task.comment.added)',
  resource_type VARCHAR(32) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Resource kind: task, project, comment, etc.',
  resource_public_id BINARY(16) NULL COMMENT 'public_id of the affected resource (null for workspace-level events)',
  title VARCHAR(255) NOT NULL COMMENT 'Human-readable notification title (i18n key or pre-rendered)',
  body TEXT NULL COMMENT 'Optional longer description',
  severity ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal' COMMENT 'AI-inferred or rule-based severity',
  channel ENUM('in_app','email','push') NOT NULL DEFAULT 'in_app' COMMENT 'Delivery channel',
  read_at DATETIME(3) NULL COMMENT 'When the user marked it read (null = unread)',
  archived_at DATETIME(3) NULL COMMENT 'When the user archived it (null = active)',
  delivered_at DATETIME(3) NULL COMMENT 'When email/push was actually sent (null for in_app only)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_notifications_public_id (public_id),
  UNIQUE KEY uniq_notifications_workspace_public_id (workspace_id, public_id),
  -- At-least-once dedup: a single (recipient, source_event, channel) tuple
  -- yields exactly one row even if the fan-out goroutine retries.
  -- MySQL UNIQUE treats NULLs as distinct, so rows with source_event_id IS NULL
  -- (scheduler / system paths) are not deduplicated by this key.
  UNIQUE KEY uniq_notifications_recipient_source_channel (recipient_user_id, source_event_id, channel),
  KEY idx_notifications_workspace_id_recipient_read (workspace_id, recipient_user_id, read_at, created_at DESC),
  KEY idx_notifications_workspace_id_recipient_archived (workspace_id, recipient_user_id, archived_at, created_at DESC),
  KEY idx_notifications_workspace_id_event_type (workspace_id, event_type),
  KEY idx_notifications_recipient_unread (recipient_user_id, read_at, archived_at, enabled),
  -- Supports cross-workspace keyset pagination on (created_at DESC, public_id DESC)
  -- for ListNotificationsForUserKeyset (no workspace_id filter).
  KEY idx_notifications_user_id_keyset (recipient_user_id, created_at, public_id),

  CONSTRAINT fk_notifications_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_notifications_source_event FOREIGN KEY (source_event_id) REFERENCES events(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-user notification entries from eventbus fan-out';

-- >>> pages.sql
-- ====================================
-- pages
-- Wiki/documentation pages with tree structure.
-- A page belongs to a workspace and optionally scopes to a project.
-- Self-referential parent_page_id enables nested page hierarchies.
-- ====================================
CREATE TABLE pages (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  project_id INT UNSIGNED NULL COMMENT 'Internal FK to projects.id (NULL = workspace-wide)',
  creator_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',
  parent_page_id INT UNSIGNED NULL COMMENT 'Internal FK to pages.id (NULL = root page)',

  title VARCHAR(500) NOT NULL COMMENT 'Page title',
  body MEDIUMTEXT NOT NULL COMMENT 'Page content',
  is_ai_generated BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Whether the page was generated by AI',
  archived_at DATETIME(3) NULL COMMENT 'Set when page is archived (distinct from enabled)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order among siblings',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_pages_public_id (public_id),
  UNIQUE KEY uniq_pages_workspace_public_id (workspace_id, public_id),
  KEY idx_pages_workspace_id_archived_at (workspace_id, archived_at),
  KEY idx_pages_workspace_id_enabled_sort_weight (workspace_id, enabled, sort_weight),
  KEY idx_pages_workspace_id_project_id (workspace_id, project_id),
  KEY idx_pages_parent_page_id (parent_page_id),
  FULLTEXT KEY ft_pages_title (title),

  CONSTRAINT fk_pages_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_pages_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE SET NULL,
  CONSTRAINT fk_pages_creator FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_pages_parent FOREIGN KEY (parent_page_id) REFERENCES pages(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Wiki/documentation pages with tree structure';

-- >>> project_members.sql
-- ====================================
-- project_members
-- Project-level access override. A user must already be a workspace_member.
