-- >>> projects.sql
-- ====================================
-- projects
-- Workspace-scoped container for tasks.
-- ====================================
CREATE TABLE projects (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',

  slug VARCHAR(63) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Workspace-local slug',
  identifier CHAR(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Human-readable project key (e.g. NF); NULL when not assigned',
  name VARCHAR(255) NOT NULL COMMENT 'Display name',
  description TEXT NULL COMMENT 'Optional description',
  color VARCHAR(16) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Hex color (e.g., #1abc9c)',
  is_archived BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Archived flag (distinct from enabled)',
  started_on DATE NULL COMMENT 'Project start date',
  ended_on DATE NULL COMMENT 'Project end date',
  feature_pages BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Toggle pages feature',
  feature_timeboxes BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Toggle timeboxes feature',
  feature_lenses BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Toggle lenses feature',
  feature_calendar BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Toggle calendar feature',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_projects_public_id (public_id),
  UNIQUE KEY uniq_projects_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_projects_workspace_id_slug_active (workspace_id, slug, active),
  KEY idx_projects_workspace_id_enabled (workspace_id, enabled),
  UNIQUE KEY uniq_projects_workspace_id_identifier_active (workspace_id, identifier, active),

  CONSTRAINT fk_projects_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Task container';

-- >>> reactions.sql
-- ====================================
-- reactions
-- Emoji reactions on tasks and comments. Exactly one of task_id
-- or comment_id must be non-NULL (enforced by CHECK constraint).
-- ====================================
CREATE TABLE reactions (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id    BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL,
  user_id      INT UNSIGNED NOT NULL,

  task_id      INT UNSIGNED NULL,
  comment_id   INT UNSIGNED NULL,
  emoji        VARCHAR(32) NOT NULL COMMENT 'Unicode emoji',

  sort_weight  INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes        TEXT NULL COMMENT 'Admin notes',
  enabled      BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at   TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_reactions_public_id (public_id),
  UNIQUE KEY uniq_reactions_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_reactions_user_task_emoji (user_id, task_id, emoji, active),
  UNIQUE KEY uniq_reactions_user_comment_emoji (user_id, comment_id, emoji, active),
  KEY idx_reactions_task_id_emoji (task_id, emoji),
  KEY idx_reactions_comment_id_emoji (comment_id, emoji),

  CONSTRAINT fk_reactions_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_reactions_user      FOREIGN KEY (user_id)      REFERENCES users(id)      ON DELETE CASCADE,
  CONSTRAINT fk_reactions_task      FOREIGN KEY (task_id)      REFERENCES tasks(id)      ON DELETE CASCADE,
  CONSTRAINT fk_reactions_comment   FOREIGN KEY (comment_id)   REFERENCES comments(id)   ON DELETE CASCADE,

  CONSTRAINT chk_reactions_target CHECK (
    (task_id IS NOT NULL AND comment_id IS NULL) OR
    (comment_id IS NOT NULL AND task_id IS NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Emoji reactions on tasks and comments';

-- >>> relation_suggestions.sql
-- ====================================
-- relation_suggestions
-- AI-generated suggestions for task relations (blocks, relates, duplicates).
-- Created when an embedding pipeline detects similarity between tasks.
-- ====================================
CREATE TABLE relation_suggestions (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  source_task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id (trigger task)',
  target_task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id (suggested relation)',

  suggested_kind ENUM('blocks','relates','duplicates') NOT NULL COMMENT 'Suggested dependency kind',
  confidence DECIMAL(5,4) NOT NULL COMMENT 'Cosine similarity score (0.0000 to 1.0000)',
  status ENUM('pending','accepted','dismissed') NOT NULL DEFAULT 'pending' COMMENT 'Resolution status',
  resolved_by INT UNSIGNED NULL COMMENT 'Internal FK to users.id (who resolved)',
  resolved_at DATETIME(3) NULL COMMENT 'When the suggestion was accepted or dismissed',

  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_relation_suggestions_public_id (public_id),
  UNIQUE KEY uniq_relation_suggestions_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_relation_suggestions_edge (source_task_id, target_task_id, suggested_kind),
  KEY idx_relation_suggestions_workspace_id_status_created_at (workspace_id, status, created_at DESC),
  KEY idx_relation_suggestions_target_task_id_status (target_task_id, status),

  CONSTRAINT fk_relation_suggestions_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_relation_suggestions_source FOREIGN KEY (source_task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_relation_suggestions_target FOREIGN KEY (target_task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_relation_suggestions_resolved_by FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT chk_relation_suggestions_no_self CHECK (source_task_id != target_task_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI-suggested task relation candidates';

-- >>> signals.sql
-- ====================================
-- signals
-- External or manually submitted signals (webhooks, manual drops, MCP emits,
-- worker ticks) that may be normalized and routed to the LLM judge for a
-- verdict. Optionally linked to a task via `task_id` (legacy fast path) and/or
-- to an arbitrary subject via `(subject_type, subject_id)`.
--
-- See ADR 0008 (docs/adr/0008-signals-and-judge-loop.md) D1 for the rationale
-- for extending this table in place rather than introducing `signals_v2`.
-- Presence signals (subject_type = 'user') are stored here directly; a
-- "who's online" projection is intentionally not materialised until a
-- presence read endpoint exists that exposes only public ids (the prior
-- v_user_presence_current view was dropped as unused — it leaked internal
-- subject/workspace ids and had no consumer).
--
-- Lifecycle columns:
--   judge_run_id      - FK to the agent_runs row that judged this signal
--                       (NULL until the judge has evaluated it).
--   judge_output_json - structured verdict from the judge (intent, target
--                       task, proposed events, confidence, reasoning excerpt).
--   confidence        - judge's reported confidence in [0.00, 1.00]; compared
--                       against ai_settings.auto_action_threshold and
--                       auto_action_rules to decide suggest / draft / auto.
--   applied_at        - set by the Applier when the verdict has been reified
--                       as one or more task events; NULL while pending or
--                       rejected.
--   expires_at        - provider-derived TTL; presence signals expire on the
--                       next presence transition, weather signals expire at
--                       the end of the window, manual signals do not expire.
--                       The retention sweep drops expired, non-applied rows
--                       for stateful kinds.
--
-- Subject columns:
--   subject_type - what the signal is about. `task_id` remains the dedicated
--                  optimised path for `subject_type='task'`; for the other
--                  three subjects, `subject_id` carries the internal FK
--                  whose target is named by `subject_type`.
--   subject_id   - internal id of the subject row (NULL when subject_type is
--                  `workspace`, since `workspace_id` already identifies the
--                  row owner). Not declared as an FK because the target table
--                  is polymorphic; integrity is enforced by handler validation
--                  at ingestion time.
-- ====================================
CREATE TABLE signals (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  task_id INT UNSIGNED NULL COMMENT 'Internal FK to tasks.id, if resolved (legacy fast path; duplicates subject_type=task / subject_id)',
  judge_run_id INT UNSIGNED NULL COMMENT 'Internal FK to agent_runs.id; set when a judge run has evaluated this signal. NULL means "not yet judged".',

  source ENUM('manual','github','slack','email','google','webhook','calendar','discord') NOT NULL COMMENT 'Originating channel. Canonical source list lives in packages/go-shared/signalwire (Sources()); this ENUM, the flow-api Huma enum tag, and the signal_kinds registry all derive from / are asserted against it. ''calendar'' is reserved for internal scheduler ticks (flow-worker calendar_event_day job, etc.) — not a user-facing webhook source. ''discord'' is the presence-discord gateway.',
  kind VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Source-specific event kind (e.g., pull_request.opened, discord.presence). Closed enumeration defined by signal_kinds/*.yaml; stays VARCHAR so new kinds do not require a schema change.',
  external_id VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'External identifier (delivery id, message ts, ...). Dedupe key for webhook double delivery.',
  payload_json JSON NOT NULL CHECK (JSON_VALID(payload_json)) COMMENT 'Raw normalized payload; anything the provider webhook cannot squeeze into the normalized columns stays here for the judge to read.',
  received_at DATETIME(3) NOT NULL COMMENT 'Time the signal was received',

  subject_type ENUM('user','task','workspace','calendar_event') NOT NULL COMMENT 'What the signal is about; selects which table subject_id targets.',
  subject_id INT UNSIGNED NULL COMMENT 'Internal id of the subject row. NULL when subject_type=workspace (workspace_id already owns the row). Polymorphic, so not declared as an FK; integrity is enforced at ingestion time.',

  judge_output_json JSON NULL CHECK (judge_output_json IS NULL OR JSON_VALID(judge_output_json)) COMMENT 'Structured verdict from the judge run (intent, target task, proposed events, reasoning excerpt). NULL until judged.',
  confidence DECIMAL(3,2) NULL COMMENT 'Judge confidence in [0.00, 1.00]; compared against ai_settings.auto_action_threshold / auto_action_rules.',
  applied_at DATETIME(3) NULL COMMENT 'When the Applier wrote the resulting task event(s). NULL while pending or rejected.',
  expires_at DATETIME(3) NULL COMMENT 'When this signal stops being authoritative. Used by the retention sweep for stateful kinds (presence, weather window).',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  CONSTRAINT chk_signals_confidence_range CHECK (confidence IS NULL OR (confidence >= 0.00 AND confidence <= 1.00)),

  UNIQUE KEY uniq_signals_public_id (public_id),
  UNIQUE KEY uniq_signals_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_signals_workspace_source_external_id (workspace_id, source, external_id),
  KEY idx_signals_workspace_id_received_at (workspace_id, received_at),
  KEY idx_signals_workspace_id_task_id (workspace_id, task_id),
  -- Supports latest-row-per-subject presence lookups and per-subject judge
  -- queue scans. observed_at-style ordering uses received_at; the index
  -- direction is descending so the "latest first" scan is index-only.
  KEY idx_signals_subject (workspace_id, subject_type, subject_id, received_at DESC),
  -- Reverse lookup from agent_runs (operator visibility: "which signal did
  -- this judge run evaluate?").
  KEY idx_signals_judge_run (judge_run_id),
  -- Retention sweep over expired, non-applied rows. MySQL 8.4 has no partial
  -- index support; the index is plain and the sweep query carries the
  -- IS NOT NULL filter.
  KEY idx_signals_expires (expires_at),
  -- Per-workspace, per-kind history (judge prompt context, autonomy metrics).
  KEY idx_signals_workspace_kind_received (workspace_id, kind, received_at),

  CONSTRAINT fk_signals_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_signals_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE SET NULL,
  CONSTRAINT fk_signals_judge_run FOREIGN KEY (judge_run_id) REFERENCES agent_runs(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Inbound signals; judged by the signal_judge agent and reified into task events by the Applier (ADR 0008)';

-- >>> task_actors.sql
-- ====================================
-- task_actors
-- Users attached to a task in a given role (assignee, reviewer, etc.).
-- ====================================
CREATE TABLE task_actors (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id',
  user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id (null when this row is an AI agent actor)',
  agent_id INT UNSIGNED NULL COMMENT 'Internal FK to ai_agents.id (null when this row is a human actor)',
  kind ENUM('user','agent') NOT NULL DEFAULT 'user' COMMENT 'Actor kind — user or AI agent',

  role ENUM('assignee','reviewer','watcher','approver') NOT NULL DEFAULT 'assignee' COMMENT 'Actor role on the task',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_task_actors_public_id (public_id),
  UNIQUE KEY uniq_task_actors_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_task_actors_task_id_user_id_role (task_id, user_id, role),
  UNIQUE KEY uniq_task_actors_task_id_agent_id_role (task_id, agent_id, role),
  KEY idx_task_actors_workspace_id_user_id (workspace_id, user_id),
  KEY idx_task_actors_workspace_id_agent_id (workspace_id, agent_id),
  -- Composite (task_id, enabled) for "actors of a task currently enabled"
  -- lookups (v_task_detail subquery, ListActorsForTask). The unique keys
  -- above lead with task_id but include user_id/agent_id, so they cannot
  -- short-circuit on the enabled predicate.
  KEY idx_task_actors_task_id_enabled (task_id, enabled),

  CONSTRAINT fk_task_actors_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_actors_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_actors_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_actors_agent FOREIGN KEY (agent_id) REFERENCES ai_agents(id) ON DELETE CASCADE,
  CONSTRAINT chk_task_actors_kind_target CHECK (
    (kind = 'user'  AND user_id  IS NOT NULL AND agent_id IS NULL) OR
    (kind = 'agent' AND agent_id IS NOT NULL AND user_id  IS NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Task actors (assignees/reviewers/...)';

-- >>> task_constraints.sql
-- ====================================
-- task_constraints
-- Declarative conditions attached to a task. The constraint engine
-- evaluates these in combination with events to derive task state.
-- ====================================
CREATE TABLE task_constraints (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id',

  kind ENUM('deadline','dependency','approval','signal','custom') NOT NULL COMMENT 'Constraint kind',
  expression TEXT NOT NULL COMMENT 'Engine-specific expression (JSON-ish DSL)',
  satisfied_at DATETIME(3) NULL COMMENT 'Time the constraint was first satisfied',
  failed_at DATETIME(3) NULL COMMENT 'Time the constraint was last evaluated as failing',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_task_constraints_public_id (public_id),
  UNIQUE KEY uniq_task_constraints_workspace_public_id (workspace_id, public_id),
  KEY idx_task_constraints_workspace_id_task_id (workspace_id, task_id),
  KEY idx_task_constraints_task_id_enabled (task_id, enabled),

  CONSTRAINT fk_task_constraints_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_constraints_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Task constraints';

-- >>> task_dependencies.sql
-- ====================================
-- task_dependencies
-- Directed edges between tasks. from_task is the dependent / originating side,
-- to_task is the target. Supported kinds:
--   - blocks       : from_task is blocked until to_task completes
--   - relates      : informational sibling link, no scheduling impact
--   - duplicates   : from_task duplicates to_task (resolved together)
--   - subtask_of   : from_task is a subtask of to_task (hierarchy)
--   - retro_of     : from_task is a retrospective draft generated by the
--                    signal_judge Applier when an event-day signal triggers
--                    a retro for to_task (the original task whose lifecycle
--                    finished and prompted the retrospective).
-- ====================================
CREATE TABLE task_dependencies (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  from_task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id (source)',
  to_task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id (target)',

  kind ENUM('blocks','relates','duplicates','subtask_of','retro_of') NOT NULL DEFAULT 'blocks' COMMENT 'Dependency kind. blocks: from_task waits on to_task. relates: informational link. duplicates: from_task duplicates to_task. subtask_of: from_task is a subtask of to_task. retro_of: created by the signal_judge Applier when an event-day signal triggers a retrospective draft task; from_task is the new draft, to_task is the original task whose lifecycle finished and prompted the retro.',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_task_dependencies_public_id (public_id),
  UNIQUE KEY uniq_task_dependencies_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_task_dependencies_edge (from_task_id, to_task_id, kind, active),
  KEY idx_task_dependencies_workspace_from (workspace_id, from_task_id),
  KEY idx_task_dependencies_workspace_to (workspace_id, to_task_id),
  -- Bare to_task_id index for ON DELETE CASCADE on tasks. The workspace-leading
  -- composite above does not satisfy to_task_id-only lookups, and the unique
  -- edge key only helps for from_task_id leading queries.
  KEY idx_task_dependencies_to_task_id (to_task_id),

  CONSTRAINT fk_task_dependencies_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_dependencies_from FOREIGN KEY (from_task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_dependencies_to FOREIGN KEY (to_task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT chk_task_dependencies_no_self CHECK (from_task_id != to_task_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Directed task dependencies';

-- >>> task_description_versions.sql
-- ====================================
-- task_description_versions
-- Task description version history (full snapshots).
-- Each edit creates a new row; the latest version_number is current.
-- ====================================
CREATE TABLE task_description_versions (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id      BINARY(16) NOT NULL                    COMMENT 'UUID v7, the only externally visible ID',
  workspace_id   INT UNSIGNED NOT NULL                   COMMENT 'Internal FK to workspaces.id',
  task_id        INT UNSIGNED NOT NULL                   COMMENT 'Internal FK to tasks.id',
  author_user_id INT UNSIGNED NULL                       COMMENT 'User who authored this version',

  version_number INT UNSIGNED NOT NULL                   COMMENT 'Monotonically increasing per task',
  body           MEDIUMTEXT NOT NULL                     COMMENT 'Full description snapshot',
  body_length    INT UNSIGNED NOT NULL DEFAULT 0         COMMENT 'Char count (cached)',

  sort_weight    INT NOT NULL DEFAULT 0                  COMMENT 'Display order',
  notes          TEXT NULL                               COMMENT 'Admin notes',
  enabled        BOOLEAN NOT NULL DEFAULT TRUE           COMMENT 'Enabled flag',
  updated_at     TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_task_desc_versions_public_id (public_id),
  UNIQUE KEY uniq_task_desc_versions_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_task_desc_versions_task_version (task_id, version_number),
  KEY idx_task_desc_versions_workspace_task (workspace_id, task_id, created_at DESC),

  CONSTRAINT fk_task_desc_versions_workspace FOREIGN KEY (workspace_id)   REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_desc_versions_task      FOREIGN KEY (task_id)        REFERENCES tasks(id)      ON DELETE CASCADE,
  CONSTRAINT fk_task_desc_versions_author    FOREIGN KEY (author_user_id) REFERENCES users(id)      ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Task description version history (full snapshots)';

-- >>> task_embeddings.sql
-- ====================================
-- task_embeddings
-- Per ADR 0003: native MySQL 9.x VECTOR storage for duplicate detection.
-- Vectors are L2-normalized before insert so cosine similarity reduces
-- to a dot product. (task_id, model) composite PK lets two models
-- coexist during a rolling re-embed; the duplicate-detection query
-- pins WHERE model = :current_model to avoid mixing vector spaces.
--
-- Internal plumbing only: never crosses the API boundary, so no
-- public_id column. workspace_id is denormalized from tasks for
-- workspace-scoped pruning / filtering without a JOIN; an explicit
-- FK to workspaces(id) ON DELETE CASCADE guarantees the denormalized
-- value cannot point at a removed workspace, even if a future writer
-- skips the JOIN through tasks.
-- ====================================
CREATE TABLE task_embeddings (
  task_id      INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Denormalized from tasks.workspace_id for scoped queries; FK guarantees consistency on workspace removal',
  model        VARCHAR(64)  NOT NULL COMMENT 'Embedding model key, e.g. mock-768',
  dim          SMALLINT UNSIGNED NOT NULL COMMENT 'Vector dimensionality (redundant with type today)',
  vector       VECTOR(768)  NOT NULL COMMENT 'L2-normalized embedding vector',
  content_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of embedded text',
  embedded_at  DATETIME(3)  NOT NULL COMMENT 'Last embed time',

  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),

  PRIMARY KEY (task_id, model),
  KEY idx_task_embeddings_workspace_id (workspace_id, task_id),
  INDEX idx_task_embeddings_model_embedded_at (model, embedded_at),

  CONSTRAINT fk_task_embeddings_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_embeddings_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Task embedding vectors for duplicate detection (ADR 0003)';

-- >>> task_event_links.sql
-- ====================================
-- task_event_links
-- M:N between tasks and calendar_events. Parallel to task_dependencies
-- (task-to-task). Encodes contribution/dependency semantics BETWEEN a
-- task and an umbrella event or milestone; distinct from the 1:1
-- projection relation stored via calendar_events.task_id + task_role.
-- ====================================
CREATE TABLE task_event_links (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  task_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to tasks.id',
  event_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendar_events.id',

  relation ENUM('contributes_to','blocks','depends_on','prep_for') NOT NULL DEFAULT 'contributes_to'
    COMMENT 'contributes_to = task is work toward an umbrella event; blocks/depends_on/prep_for reserved for future',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order within an event''s linked-task list',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag (soft-disable)',
  -- Liveness marker scoping the unique key below to live rows: 1 while
  -- enabled, NULL once soft-deleted, so tombstones leave the index
  -- rather than colliding with each other. See the soft-delete rule in
  -- sql/core/conformance/schema/40-soft-delete-uniqueness.sql.
  active TINYINT UNSIGNED GENERATED ALWAYS AS (IF(enabled, 1, NULL)) VIRTUAL COMMENT 'NULL once soft-deleted; exists only to scope the unique key below to live rows',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_task_event_links_public_id (public_id),
  UNIQUE KEY uniq_task_event_links_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_task_event_links_task_event_relation (task_id, event_id, relation, active) COMMENT 'At most one live link per (task, event, relation); revoked ones drop out via active',
  KEY idx_task_event_links_workspace_event (workspace_id, event_id, enabled),
  KEY idx_task_event_links_workspace_task (workspace_id, task_id, enabled),

  CONSTRAINT fk_task_event_links_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_event_links_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  CONSTRAINT fk_task_event_links_event FOREIGN KEY (event_id) REFERENCES calendar_events(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='M:N task-to-event relationships (umbrella events, milestones)';

