-- >>> _v_task_list_all.sql
-- v_task_list_all
-- Base projection that includes BOTH active and archived tasks.
-- Acts as the single source of column definitions for the task list family.
-- Consumers should prefer v_task_list (active) or v_task_list_archived
-- (archived) which filter this base view by archived_at. MySQL 8.4 expands
-- single-level views via the MERGE optimizer, so there is no runtime cost.
--
-- The three child-table columns are correlated scalar subqueries rather
-- than joined derived tables, and that is a tenancy property, not a
-- micro-optimisation. A derived table cannot see the outer workspace
-- predicate, so MySQL has to materialise it over every row in the
-- instance before the join can filter: reading one 200-task project meant
-- aggregating every task_actors and task_labels row of every tenant
-- first, and one large tenant slowed the list down for all the others.
-- Correlating on t.id instead evaluates each subquery per emitted row
-- against the child tables' task_id indexes, so the work scales with the
-- page, not with the instance. Adding a fourth child column belongs in
-- the same shape; a LEFT JOIN over a GROUP BY reintroduces the problem.
--
-- Correlating on t.id also carries the enabled check that the previous
-- shape spelled out: the subqueries only ever see the outer row, which
-- the final WHERE already restricts to enabled tasks, so a child row of
-- a soft-disabled task cannot surface here.
CREATE OR REPLACE ALGORITHM=MERGE VIEW v_task_list_all AS
SELECT
  t.workspace_id,
  t.project_id,
  t.created_by_user_id,
  t.public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  p.identifier AS project_identifier,
  t.task_number,
  pt.public_id AS parent_task_public_id,
  t.title,
  t.visibility,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.completed_at,
  t.archived_at,
  t.sort_weight,
  t.updated_at,
  t.created_at,
  -- The first assignee in display order, and NULL when that actor is an
  -- AI agent or a disabled user -- the ORDER BY picks the row, the LEFT
  -- JOIN decides whether it has a name to show. Resolving to the *next*
  -- assignee instead would silently promote someone the workspace did
  -- not put first.
  (SELECT u.public_id
     FROM task_actors ta
     LEFT JOIN users u
       ON u.id = ta.user_id AND u.enabled = TRUE
    WHERE ta.task_id = t.id
      AND ta.enabled = TRUE
      AND ta.role = 'assignee'
    ORDER BY ta.sort_weight ASC, ta.id ASC
    LIMIT 1) AS primary_assignee_public_id,
  -- Counts human assignees only; the INNER JOIN drops agent actors
  -- (user_id IS NULL) and actors whose user has been disabled.
  (SELECT COUNT(*)
     FROM task_actors ta
     INNER JOIN users u
       ON u.id = ta.user_id AND u.enabled = TRUE
    WHERE ta.task_id = t.id
      AND ta.enabled = TRUE
      AND ta.role = 'assignee') AS assignee_count,
  -- label_ids is a comma-separated list of UUID *text*, not of raw
  -- BINARY(16). Concatenating the binary form is unrecoverable in both
  -- directions: 0x2C occurs inside legitimate UUIDv7 bytes so the reader
  -- cannot tell a separator from payload, and the bytes are not valid
  -- UTF-8 so JSON encoding replaces them with U+FFFD before the reader
  -- ever sees them. BIN_TO_UUID uses swap_flag 0 to match the
  -- UUID_TO_BIN(?, 0) form every writer uses.
  --
  -- The SUBSTRING_INDEX cap is what keeps GROUP_CONCAT honest. Its
  -- result is clipped at group_concat_max_len (1024 bytes by default)
  -- with no error and no marker, which at 37 bytes per entry would cut
  -- the 28th UUID in half and hand the reader a malformed id. Cutting at
  -- the 20th entry lands on byte 739, so the clip can only ever damage
  -- text this expression has already discarded: the column is either the
  -- whole list or its first 20 entries in display order -- never a
  -- half-written one. The list-row badge strip is the only consumer.
  -- Callers needing every label of a task read the task's label
  -- collection directly.
  -- The COALESCE sits inside SUBSTRING_INDEX, not around the subquery:
  -- a task with no labels aggregates to NULL, and the empty string is
  -- what "no labels" already meant to every consumer. Wrapping the
  -- subquery from the outside instead leaves the generated reader with
  -- no column type to work from and it falls back to interface{}.
  (SELECT SUBSTRING_INDEX(
            COALESCE(GROUP_CONCAT(BIN_TO_UUID(l.public_id, 0)
              ORDER BY tl.sort_weight ASC, tl.id ASC SEPARATOR ','), ''),
            ',', 20)
     FROM task_labels tl
     INNER JOIN labels l
       ON l.id = tl.label_id AND l.enabled = TRUE
    WHERE tl.task_id = t.id
      AND tl.enabled = TRUE) AS label_ids
FROM tasks t
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks pt
  ON pt.id = t.parent_task_id AND pt.enabled = TRUE
WHERE t.enabled = TRUE;

-- >>> v_admin_users.sql
-- v_admin_users
-- Instance-scoped user view for admin panel. Unlike v_users, this is NOT
-- workspace-scoped and includes all users regardless of membership.
CREATE OR REPLACE VIEW v_admin_users AS
SELECT
  u.id,
  u.public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  u.avatar_storage_object_id,
  so_avatar.public_id AS avatar_storage_object_public_id,
  u.locale,
  u.timezone,
  u.country,
  u.last_login_at,
  u.email_verified_at,
  u.enabled,
  u.created_at,
  u.updated_at,
  (SELECT COUNT(*) FROM workspace_members wm
     WHERE wm.user_id = u.id AND wm.enabled = TRUE) AS workspace_count,
  EXISTS(SELECT 1 FROM instance_admins ia
     WHERE ia.user_id = u.id AND ia.enabled = TRUE
       AND ia.revoked_at IS NULL) AS is_instance_admin
FROM users u
LEFT JOIN storage_objects so_avatar
  ON so_avatar.id = u.avatar_storage_object_id AND so_avatar.enabled = TRUE;

-- >>> v_audit_recent.sql
-- v_audit_recent
-- Recent audit events projected for the admin UI. api_key values are
-- never present here; metadata_json is already redacted at write time.
CREATE OR REPLACE VIEW v_audit_recent AS
SELECT
  al.workspace_id,
  al.public_id,
  actor.public_id AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  al.action,
  al.resource_type,
  al.resource_public_id,
  al.ip_address,
  al.user_agent,
  al.metadata_json,
  al.occurred_at
FROM audit_logs al
INNER JOIN workspaces w
  ON w.id = al.workspace_id AND w.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = al.actor_user_id AND actor.enabled = TRUE
WHERE al.enabled = TRUE;

-- >>> v_comment_for_task.sql
-- v_comment_for_task
-- Shared projection used by ListCommentsForTask (offset variant) and
-- ListCommentsForTaskKeyset (keyset variant). Encapsulates the comments
-- + tasks + users JOINs so both query variants stay aligned on
-- visibility (`enabled = TRUE` propagation) and column shape.
--
-- The author is LEFT JOINed. A comment is part of the task's history and
-- belongs to the task, not to the account that typed it, so suspending
-- that account must not delete the discussion for everyone else on the
-- team. `enabled = TRUE` stays in the ON clause, so a suspended author's
-- identity columns come back NULL and the comment renders as written by an
-- unknown user. The rule this follows: `enabled = TRUE` may gate a row only
-- when the user is what the row is about (membership, credentials, actor
-- lists); when the user is merely the byline on someone else's content, it
-- gates the byline.
CREATE OR REPLACE ALGORITHM=MERGE VIEW v_comment_for_task AS
SELECT
  c.workspace_id,
  c.task_id,
  t.public_id AS task_public_id,
  c.public_id,
  u.public_id AS author_public_id,
  u.display_name AS author_display_name,
  u.avatar_url AS author_avatar_url,
  u.avatar_storage_object_id AS author_avatar_storage_object_id,
  so_author_avatar.public_id AS author_avatar_storage_object_public_id,
  c.body,
  c.edited_at,
  c.updated_at,
  c.created_at
FROM comments c
INNER JOIN workspaces w ON w.id = c.workspace_id AND w.enabled = TRUE
INNER JOIN tasks t ON t.id = c.task_id AND t.enabled = TRUE
LEFT JOIN users u ON u.id = c.author_id AND u.enabled = TRUE
LEFT JOIN storage_objects so_author_avatar
  ON so_author_avatar.id = u.avatar_storage_object_id AND so_author_avatar.enabled = TRUE
WHERE c.enabled = TRUE;

-- >>> v_inbox.sql
-- v_inbox
-- Aggregated inbox: signals that have arrived in a workspace with optional
-- task linkage. Consumers filter by workspace_id and archive/snooze state.
CREATE OR REPLACE VIEW v_inbox AS
SELECT
  s.workspace_id,
  w.public_id AS workspace_public_id,
  s.public_id,
  t.public_id AS task_public_id,
  t.title AS task_title,
  -- The task's own ACL columns ride along so a consumer can apply the
  -- Layer 4 visibility rule. The view cannot apply it itself: it takes
  -- no parameters, and the answer depends on who is reading. Exposing
  -- the inputs here is what lets every consumer reach the same verdict
  -- instead of each inventing one.
  t.visibility AS task_visibility,
  t.project_id AS task_project_id,
  t.created_by_user_id AS task_created_by_user_id,
  t.id AS task_internal_id,
  s.source,
  s.kind,
  s.external_id,
  s.payload_json,
  s.received_at,
  s.updated_at,
  s.created_at
FROM signals s
INNER JOIN workspaces w
  ON w.id = s.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks t
  ON t.id = s.task_id AND t.enabled = TRUE
WHERE s.enabled = TRUE;

-- >>> v_instance_audit_logs.sql
-- v_instance_audit_logs
-- Instance-wide audit log joined with actor user and optional workspace.
-- Disabled actor / workspace rows are masked (LEFT JOIN with enabled = TRUE
-- on the ON clause). If an audit consumer needs to surface forensic data
-- for soft-disabled tenants, query instance_audit_logs directly rather than
-- through this view.
CREATE OR REPLACE VIEW v_instance_audit_logs AS
SELECT
  ial.public_id,
  actor.public_id   AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  ial.action,
  ws.public_id      AS target_workspace_public_id,
  ws.name           AS target_workspace_name,
  ial.target_resource_type,
  ial.target_resource_public_id,
  ial.ip_address,
  ial.user_agent,
  ial.payload_json,
  ial.occurred_at
FROM instance_audit_logs ial
LEFT JOIN users actor ON actor.id = ial.actor_user_id AND actor.enabled = TRUE
LEFT JOIN workspaces ws ON ws.id = ial.target_workspace_id AND ws.enabled = TRUE
WHERE ial.enabled = TRUE;

-- >>> v_my_tasks.sql
-- v_my_tasks
-- Tasks where a user is attached as an actor. Consumers filter on
-- user_public_id in addition to workspace_id.
CREATE OR REPLACE VIEW v_my_tasks AS
SELECT
  t.workspace_id,
  t.public_id,
  u.public_id AS user_public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  t.title,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  a.role AS actor_role,
  t.updated_at,
  t.created_at
FROM task_actors a
INNER JOIN tasks t
  ON t.id = a.task_id AND t.enabled = TRUE
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN users u
  ON u.id = a.user_id AND u.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
WHERE a.enabled = TRUE;

