-- v_projects
-- Project listing with basic metadata. Workspace-scoped.
CREATE OR REPLACE VIEW v_projects AS
SELECT
  p.workspace_id,
  p.public_id,
  p.slug,
  p.identifier,
  p.name,
  p.description,
  p.color,
  p.is_archived,
  p.started_on,
  p.ended_on,
