-- >>> v_task_detail.sql
-- v_task_detail
-- Detailed task projection. Uses correlated subqueries for counts to
-- avoid Cartesian products from multiple LEFT JOINs on 1:N tables.
-- Each correlated subquery propagates `enabled = TRUE` through the chain
-- of parent rows it touches, so a disabled user/agent/label/target task
-- never inflates the count exposed on the detail page.
--
-- Archived tasks are included on purpose. Archiving is a listing
-- decision, not a deletion: the archive room lists archived rows and
-- links to them, and every task-detail route (detail, infer-state,
-- transitions, duplicates, steps, handoff, replay) resolves through
-- this view. Filtering here made all of those 404 for exactly the rows
-- the archive room advertises. Which tasks a list shows is settled by
-- picking v_task_list or v_task_list_archived, one level up.
-- t.enabled = FALSE is soft-deletion and does stay excluded.
CREATE OR REPLACE VIEW v_task_detail AS
SELECT
  t.workspace_id,
  w.public_id AS workspace_public_id,
  t.public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  p.identifier AS project_identifier,
  t.task_number,
  pt.public_id AS parent_task_public_id,
  creator.public_id AS created_by_user_public_id,
  t.title,
  t.description,
  t.visibility,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.completed_at,
  t.archived_at,
  t.agent_memo,
  -- Current AI agent assignee (kind='agent', role='assignee', enabled chain).
  -- When multiple enabled agent-assignee rows exist for the same task, expose
  -- the most recently updated row (ties broken by id desc) so the detail view
  -- reflects the latest handoff target.
  (SELECT ag.public_id FROM task_actors a
     INNER JOIN ai_agents ag ON ag.id = a.agent_id AND ag.enabled = TRUE
     WHERE a.task_id = t.id AND a.kind = 'agent' AND a.role = 'assignee' AND a.enabled = TRUE
     ORDER BY a.updated_at DESC, a.id DESC
     LIMIT 1) AS agent_assignee_public_id,
  CAST(COALESCE((SELECT ag.name FROM task_actors a
     INNER JOIN ai_agents ag ON ag.id = a.agent_id AND ag.enabled = TRUE
     WHERE a.task_id = t.id AND a.kind = 'agent' AND a.role = 'assignee' AND a.enabled = TRUE
     ORDER BY a.updated_at DESC, a.id DESC
     LIMIT 1), '') AS CHAR(255)) AS agent_assignee_name,
  (SELECT COUNT(*) FROM task_constraints c
     WHERE c.task_id = t.id AND c.enabled = TRUE) AS constraint_count,
  (SELECT COUNT(*) FROM task_constraints c
     WHERE c.task_id = t.id AND c.enabled = TRUE AND c.satisfied_at IS NOT NULL) AS constraint_satisfied_count,
  (SELECT COUNT(*) FROM task_dependencies d
     INNER JOIN tasks dt ON dt.id = d.to_task_id AND dt.enabled = TRUE
     WHERE d.from_task_id = t.id AND d.enabled = TRUE) AS dependency_count,
  (SELECT COUNT(*) FROM task_actors a
     LEFT JOIN users au ON au.id = a.user_id
     LEFT JOIN ai_agents ag ON ag.id = a.agent_id
     WHERE a.task_id = t.id AND a.enabled = TRUE
       AND ((a.kind = 'user'  AND au.id IS NOT NULL AND au.enabled = TRUE)
         OR (a.kind = 'agent' AND ag.id IS NOT NULL AND ag.enabled = TRUE))) AS actor_count,
  (SELECT COUNT(*) FROM task_labels tl
     INNER JOIN labels l ON l.id = tl.label_id AND l.enabled = TRUE
     WHERE tl.task_id = t.id AND tl.enabled = TRUE) AS label_count,
  t.sort_weight,
  t.updated_at,
  t.created_at
FROM tasks t
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks pt
  ON pt.id = t.parent_task_id AND pt.enabled = TRUE
LEFT JOIN users creator
  ON creator.id = t.created_by_user_id AND creator.enabled = TRUE
WHERE t.enabled = TRUE;

-- >>> v_task_list.sql
-- v_task_list
-- Active (non-archived) task projection for list / board views.
-- Thin filter over v_task_list_all; column definitions live in the base view.
CREATE OR REPLACE ALGORITHM=MERGE VIEW v_task_list AS
SELECT v.*
FROM v_task_list_all v
WHERE v.archived_at IS NULL;

-- >>> v_task_list_archived.sql
-- v_task_list_archived
-- Archived-only task projection. Thin filter over v_task_list_all;
-- column definitions live in the base view.
CREATE OR REPLACE ALGORITHM=MERGE VIEW v_task_list_archived AS
SELECT v.*
FROM v_task_list_all v
WHERE v.archived_at IS NOT NULL;

-- >>> v_task_timeline.sql
-- v_task_timeline
-- Timeline of events related to tasks. Merges events with the owning
-- task's public_id so the UI can render without touching internal ids.
--
-- Exposes the third actor source (`actor_system_source`, ADR 0008 D8) and
-- the signal traceability link (`triggered_by_signal_public_id`, ADR 0008
-- D4) so the timeline UI can render "Discord said idle -> judge ran ->
-- task completed" as a single causal chain. The signal join uses alias
-- `tsig` (triggering signal) to avoid colliding with any future signals
-- JOIN that might use the conventional `s` alias.
--
-- Reversal projection (ADR 0008 D4 / J5): `reverses_event_public_id`
-- surfaces the target event's public_id when this row is a compensating
-- reverse, sourced from a self-join aliased `e_rev` (reverse target).
-- `was_reversed` is TRUE when some other enabled event points back to this
-- row via reverses_event_id; the correlated EXISTS subquery uses alias
-- `e_chk` (reverse check) and is backed by idx_events_reverses
-- (workspace_id, reverses_event_id) so the per-row scan stays index-only.
CREATE OR REPLACE VIEW v_task_timeline AS
SELECT
  e.workspace_id,
  e.id AS event_id,
  e.public_id,
  t.public_id AS task_public_id,
  p.public_id AS project_public_id,
  actor.public_id AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  agent.public_id AS actor_agent_public_id,
  CAST(COALESCE(agent.name, '') AS CHAR(255)) AS actor_agent_name,
  e.actor_system_source,
  tsig.public_id AS triggered_by_signal_public_id,
  e_rev.public_id AS reverses_event_public_id,
  EXISTS (
    SELECT 1 FROM events e_chk
    WHERE e_chk.workspace_id = e.workspace_id
      AND e_chk.reverses_event_id = e.id
      AND e_chk.enabled = TRUE
  ) AS was_reversed,
  e.type,
  e.payload_json,
  e.occurred_at
FROM events e
INNER JOIN workspaces w
  ON w.id = e.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks t
  ON t.id = e.task_id AND t.enabled = TRUE
LEFT JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = e.actor_user_id AND actor.enabled = TRUE
LEFT JOIN ai_agents agent
  ON agent.id = e.actor_agent_id AND agent.enabled = TRUE
LEFT JOIN signals tsig
  ON tsig.id = e.triggered_by_signal_id AND tsig.enabled = TRUE
LEFT JOIN events e_rev
  ON e_rev.id = e.reverses_event_id AND e_rev.enabled = TRUE
WHERE e.enabled = TRUE;

-- >>> v_users.sql
-- v_users
-- Workspace-scoped user projection. Joins workspace_members so the view
-- carries workspace_id for tenant guards. Internal ids are not selected.
CREATE OR REPLACE VIEW v_users AS
SELECT
  wm.workspace_id,
  u.public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  u.avatar_storage_object_id,
  so_avatar.public_id AS avatar_storage_object_public_id,
  u.locale,
  u.timezone,
  u.country,
  u.week_start,
  u.theme_preference,
  u.calendar_shift_default,
  wm.role AS workspace_role,
  u.last_login_at,
  u.updated_at,
  u.created_at
FROM users u
INNER JOIN workspace_members wm
  ON wm.user_id = u.id AND wm.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = wm.workspace_id AND w.enabled = TRUE
LEFT JOIN storage_objects so_avatar
  ON so_avatar.id = u.avatar_storage_object_id AND so_avatar.enabled = TRUE
WHERE u.enabled = TRUE;

-- >>> v_workspace_activity.sql
-- v_workspace_activity
-- Unified read model that streams audit_logs, ai_invocations, and
-- mcp_invocations into one cursor-paginated activity timeline per
-- workspace. Built so the workspace dashboard / admin UI can issue a
-- single indexed query instead of three round-trips with manual merge.
--
-- Projection contract:
--   workspace_id            -- internal FK; required for filtering, never returned by API
--   public_id               -- BINARY(16); the source row's UUID (unique per source_table)
--   source                  -- 'audit' | 'ai' | 'mcp' (literal)
--   source_table            -- literal source table name (for debug / drill-down joins)
--   occurred_at             -- DATETIME(3); audit.occurred_at / ai.invoked_at / mcp.invoked_at
--   actor_user_public_id    -- BINARY(16) NULL; resolved via users.id when the source row has an actor
--   actor_kind              -- 'user' | 'agent' | 'system'
--
-- actor_kind is decided by which actor column the source row bound, and
-- the ai and mcp legs answer it the same way: an agent_id wins over a
-- user_id, because an agent-owned token still records the human who
-- minted it and reporting that human as the actor puts a person's face
-- on work an agent did. The audit leg has no agent column, so its rows
-- can only be 'user' or 'system'; that is why an MCP call also carrying
-- an audit_logs row shows up twice with different actor_kind values.
-- Collapsing the two is not a view-level fix — audit_logs would need an
-- actor_agent_id of its own — and dropping the mcp leg would drop the
-- only leg that can say 'agent' about a tool call.
--   action                  -- audit.action / ai.purpose / mcp.tool_name
--   resource_type           -- audit.resource_type / 'ai_invocation' / 'mcp_invocation'
--   resource_public_id      -- audit.resource_public_id / source's own public_id for ai/mcp
--   severity                -- 'info' | 'warn' | 'error' (derived from status enum)
--
-- UNION ALL (not UNION) — rows are intrinsically distinct by (source,
-- public_id) and we want to skip the dedup sort. Each leg filters
-- enabled = TRUE on its source row to honour the soft-delete contract.
CREATE OR REPLACE VIEW v_workspace_activity AS
SELECT
  al.workspace_id,
  al.public_id,
  CAST('audit' AS CHAR(8) CHARACTER SET utf8mb4) AS source,
  CAST('audit_logs' AS CHAR(32) CHARACTER SET utf8mb4) AS source_table,
  al.occurred_at,
  actor.public_id AS actor_user_public_id,
  CAST(IF(al.actor_user_id IS NULL, 'system', 'user') AS CHAR(8) CHARACTER SET utf8mb4) AS actor_kind,
  al.action,
  al.resource_type,
  al.resource_public_id,
  CAST('info' AS CHAR(8) CHARACTER SET utf8mb4) AS severity
FROM audit_logs al
INNER JOIN workspaces w
  ON w.id = al.workspace_id AND w.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = al.actor_user_id AND actor.enabled = TRUE
WHERE al.enabled = TRUE

UNION ALL

SELECT
  ai.workspace_id,
  ai.public_id,
  CAST('ai' AS CHAR(8) CHARACTER SET utf8mb4) AS source,
  CAST('ai_invocations' AS CHAR(32) CHARACTER SET utf8mb4) AS source_table,
  ai.invoked_at AS occurred_at,
  actor.public_id AS actor_user_public_id,
  CAST(
    CASE
      WHEN ai.agent_id IS NOT NULL THEN 'agent'
      WHEN ai.user_id IS NOT NULL THEN 'user'
      ELSE 'system'
    END
    AS CHAR(8) CHARACTER SET utf8mb4
  ) AS actor_kind,
  ai.purpose AS action,
  CAST('ai_invocation' AS CHAR(64) CHARACTER SET utf8mb4) AS resource_type,
  ai.public_id AS resource_public_id,
  CAST(
    CASE ai.status
      WHEN 'ok' THEN 'info'
      WHEN 'blocked' THEN 'warn'
      ELSE 'error'
    END
    AS CHAR(8) CHARACTER SET utf8mb4
  ) AS severity
FROM ai_invocations ai
INNER JOIN workspaces w
  ON w.id = ai.workspace_id AND w.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = ai.user_id AND actor.enabled = TRUE
WHERE ai.enabled = TRUE

UNION ALL

SELECT
  mi.workspace_id,
  mi.public_id,
  CAST('mcp' AS CHAR(8) CHARACTER SET utf8mb4) AS source,
  CAST('mcp_invocations' AS CHAR(32) CHARACTER SET utf8mb4) AS source_table,
  mi.invoked_at AS occurred_at,
  actor.public_id AS actor_user_public_id,
  CAST(
    CASE
      WHEN mi.agent_id IS NOT NULL THEN 'agent'
      WHEN mi.user_id IS NOT NULL THEN 'user'
      ELSE 'system'
    END
    AS CHAR(8) CHARACTER SET utf8mb4
  ) AS actor_kind,
  mi.tool_name AS action,
  CAST('mcp_invocation' AS CHAR(64) CHARACTER SET utf8mb4) AS resource_type,
  mi.public_id AS resource_public_id,
  CAST(
    CASE mi.status
      WHEN 'ok' THEN 'info'
      WHEN 'denied' THEN 'warn'
      ELSE 'error'
    END
    AS CHAR(8) CHARACTER SET utf8mb4
  ) AS severity
FROM mcp_invocations mi
INNER JOIN workspaces w
  ON w.id = mi.workspace_id AND w.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = mi.user_id AND actor.enabled = TRUE
WHERE mi.enabled = TRUE;

-- >>> v_workspace_members.sql
-- v_workspace_members
-- Workspace membership joined with user display fields.
CREATE OR REPLACE VIEW v_workspace_members AS
SELECT
  wm.workspace_id,
  wm.public_id,
  u.public_id AS user_public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  u.avatar_storage_object_id,
  so_avatar.public_id AS avatar_storage_object_public_id,
  wm.role,
  wm.invited_at,
  wm.joined_at,
  wm.updated_at,
  wm.created_at
FROM workspace_members wm
INNER JOIN users u
  ON u.id = wm.user_id AND u.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = wm.workspace_id AND w.enabled = TRUE
LEFT JOIN storage_objects so_avatar
  ON so_avatar.id = u.avatar_storage_object_id AND so_avatar.enabled = TRUE
WHERE wm.enabled = TRUE;

DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_del`;
DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_ins`;
DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_upd`;

-- >>> trg_calendar_events_projection_guard_del.sql
-- ====================================
-- trg_calendar_events_projection_guard_del
-- DELETE half of the calendar_events projection guard. See
-- trg_calendar_events_projection_guard_upd for the full rationale.
--
-- Nothing in the product hard-deletes a calendar event: removal is
-- enabled = FALSE, which the UPDATE guard already covers. This trigger
-- exists for the writer that reaches past the product and issues a real
-- DELETE, which would drop a task's projection with no compensating
-- row in `events` and no way to notice afterwards.
--
-- Workspace and calendar teardown are unaffected: MySQL does not
-- activate triggers for rows removed by a foreign key referential
-- action.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_del
BEFORE DELETE ON calendar_events
FOR EACH ROW
BEGIN
  IF OLD.task_id IS NOT NULL AND @nf_item_projection_engine IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'task-projected calendar events may only be deleted by the item projection engine';
  END IF;
END$$

DELIMITER ;

-- >>> trg_calendar_events_projection_guard_ins.sql
-- ====================================
-- trg_calendar_events_projection_guard_ins
-- INSERT half of the calendar_events projection guard. See
-- trg_calendar_events_projection_guard_upd for the full rationale.
--
-- Enforces, unconditionally:
--   (task_id IS NULL) = (task_role IS NULL)
--   task_id IS NULL OR recurrence_rule IS NULL
--   (recurrence_parent_id IS NULL) = (recurrence_original_start IS NULL)
--   recurrence_parent_id IS NULL OR recurrence_rule IS NULL
--   recurrence_parent_id IS NULL OR task_id IS NULL
--
-- and, unless @nf_item_projection_engine is set: a row may not be
-- created already linked to a task.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_ins
BEFORE INSERT ON calendar_events
FOR EACH ROW
BEGIN
  IF (NEW.task_id IS NULL) <> (NEW.task_role IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.task_id and task_role must be set or cleared together';
  END IF;

  IF NEW.task_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not carry a recurrence rule';
  END IF;

  IF (NEW.recurrence_parent_id IS NULL) <> (NEW.recurrence_original_start IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.recurrence_parent_id and recurrence_original_start must be set or cleared together';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'an occurrence override may not carry a recurrence rule of its own';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.task_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not be an occurrence override';
  END IF;

  IF NEW.task_id IS NOT NULL AND @nf_item_projection_engine IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'task-projected calendar events may only be written by the item projection engine';
  END IF;
END$$

DELIMITER ;

-- >>> trg_calendar_events_projection_guard_upd.sql
-- ====================================
-- trg_calendar_events_projection_guard_upd
-- Keeps a task-projected calendar event in step with the task it
-- projects, from the database rather than from application code.
--
-- Two classes of rule live here.
--
-- Unconditional shape invariants. These would be CHECK constraints,
-- but MySQL 8.4+ forbids a CHECK that references a column used in a
-- foreign key referential action, and task_id carries ON DELETE SET
-- NULL. A trigger has no such restriction:
--
--   (task_id IS NULL) = (task_role IS NULL)
--   task_id IS NULL OR recurrence_rule IS NULL
--   (recurrence_parent_id IS NULL) = (recurrence_original_start IS NULL)
--   recurrence_parent_id IS NULL OR recurrence_rule IS NULL
--   recurrence_parent_id IS NULL OR task_id IS NULL
--
-- Ownership of the projection. task_id / task_role and the columns
-- that mirror a task field (title, start_at, end_at, and the
-- enabled soft-delete flag) may only be written by the projection
-- engine, which moves the task and the event together inside one
-- transaction and appends the matching item.* row to `events`. A
-- writer that changes them directly desyncs the pair and emits no
-- domain event, which is exactly the drift the reconciler reports as
-- item_inconsistency_total.
--
-- Columns with no task-side counterpart (memo, location, visibility,
-- show_as, url, block_label, ...) stay freely editable on a projected
-- row: they carry no invariant, so guarding them would only make the
-- calendar UI lie about what it can offer.
--
-- The engine opts in by setting @nf_item_projection_engine = 1 on the
-- connection before its write and clearing it afterwards; the variable
-- is session-scoped, so a fresh connection is always guarded. In a
-- deployment without the flow layer task_id is always NULL and none of
-- these branches can fire.
--
-- Comparisons use <=> because start_at / end_at / task_id are nullable
-- and `<>` yields NULL — never true — as soon as either side is NULL.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_upd
BEFORE UPDATE ON calendar_events
FOR EACH ROW
BEGIN
  IF (NEW.task_id IS NULL) <> (NEW.task_role IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.task_id and task_role must be set or cleared together';
  END IF;

  IF NEW.task_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not carry a recurrence rule';
  END IF;

  IF (NEW.recurrence_parent_id IS NULL) <> (NEW.recurrence_original_start IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.recurrence_parent_id and recurrence_original_start must be set or cleared together';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'an occurrence override may not carry a recurrence rule of its own';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.task_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not be an occurrence override';
  END IF;

  IF @nf_item_projection_engine IS NULL THEN
    IF NOT (NEW.task_id <=> OLD.task_id) OR NOT (NEW.task_role <=> OLD.task_role) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'the task projection link may only be changed by the item projection engine';
    END IF;

    IF OLD.task_id IS NOT NULL
       AND (NOT (NEW.title <=> OLD.title)
         OR NOT (NEW.start_at <=> OLD.start_at)
         OR NOT (NEW.end_at <=> OLD.end_at)
         OR NOT (NEW.enabled <=> OLD.enabled)) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'title, start_at, end_at and enabled mirror the linked task and may only be written by the item projection engine';
    END IF;
  END IF;
END$$

DELIMITER ;

DROP TRIGGER IF EXISTS `trg_tasks_derived_state_guard`;

-- >>> trg_tasks_derived_state_guard.sql
-- ====================================
-- trg_tasks_derived_state_guard
-- Enforces the convention that tasks.derived_state is computed from
-- constraints + events and may only be mutated by the events engine.
-- Any non-engine UPDATE that changes derived_state is rejected with
-- SQLSTATE '45000'.
--
-- The events engine (apps/flow-api/internal/events/...) opts in by
-- setting the session variable @nf_derived_state_engine = 1 prior to
-- its UPDATE; a non-NULL value bypasses the guard for that session.
-- Setting the variable back to NULL (or opening a new connection) re-
-- arms the guard.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_tasks_derived_state_guard
BEFORE UPDATE ON tasks
FOR EACH ROW
BEGIN
  IF NEW.derived_state <> OLD.derived_state
     AND @nf_derived_state_engine IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'derived_state mutation must go through the events engine';
  END IF;
END$$

DELIMITER ;

SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;
